static unsigned int func_3(unsigned int x)
{
    Triple t;
    t.a = x + 3u;
    t.b = x * 4u;
    t.c = t.a ^ t.b;
    while (t.c > 1003u) {
        t.c = t.c / 2u + t.a % 6u;
    }
    return t.a + t.b + t.c;
}

